{
  "name": "NESE Report Architect",
  "description": "Una eina professional per a psicopedagogs i EAPs per generar informes de Necessitats Específiques de Suport Educatiu (NESE) amb el suport d'IA, seguint el Decret 150/2017."
}

export enum AppStep {
  INPUT = 'input',
  CONCLUSIONS = 'conclusions',
  ORIENTATIONS = 'orientations',
  FINALIZE = 'finalize'
}

export interface ReportData {
  rawInput: string;
  selectedBlocks: number[];
  conclusions: string;
  orientations: string;
  studentName: string;
  schoolYear: string;
}

export interface BlockOption {
  id: number;
  label: string;
  description: string;
}

import { GoogleGenAI } from "@google/genai";
import { SYSTEM_PROMPT_PART_1, SYSTEM_PROMPT_PART_2 } from "../constants";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  async generateConclusions(input: string, selectedBlocks: number[]): Promise<string> {
    const blocksText = selectedBlocks.join(", ");
    const prompt = `Aquí tens la informació de l'alumne:\n\n${input}\n\nL'usuari ha seleccionat els següents blocs per incloure: ${blocksText}. Redacta l'apartat 1 de l'informe seguint les instruccions.`;

    const response = await this.ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_PROMPT_PART_1,
        temperature: 0.7,
      },
    });

    return response.text || "Error generant conclusions.";
  }

  async generateOrientations(conclusions: string): Promise<string> {
    const prompt = `Basant-te en les següents conclusions de l'apartat 1, redacta l'apartat 2 d'orientacions:\n\n${conclusions}`;

    const response = await this.ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_PROMPT_PART_2,
        temperature: 0.7,
      },
    });

    return response.text || "Error generant orientacions.";
  }
}

export const geminiService = new GeminiService();

import React, { useRef, useEffect } from 'react';

interface RichTextEditorProps {
  value: string;
  onChange: (value: string) => void;
  className?: string;
  label?: string;
}

export const RichTextEditor: React.FC<RichTextEditorProps> = ({ value, onChange, className = '', label }) => {
  const editorRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (editorRef.current && editorRef.current.innerHTML !== value) {
      editorRef.current.innerHTML = value;
    }
  }, [value]);

  const handleInput = () => {
    if (editorRef.current) {
      onChange(editorRef.current.innerHTML);
    }
  };

  const execCommand = (command: string, value: string = '') => {
    document.execCommand(command, false, value);
    handleInput();
  };

  return (
    <div className={`flex flex-col border border-slate-200 rounded-lg bg-white overflow-hidden ${className}`}>
      {label && <label className="px-4 py-2 text-xs font-semibold text-slate-500 bg-slate-50 border-b">{label}</label>}
      <div className="flex items-center gap-1 p-2 border-b bg-slate-50 no-print">
        <button onClick={() => execCommand('bold')} className="p-2 hover:bg-slate-200 rounded" title="Negreta"><i className="fas fa-bold"></i></button>
        <button onClick={() => execCommand('italic')} className="p-2 hover:bg-slate-200 rounded" title="Cursiva"><i className="fas fa-italic"></i></button>
        <div className="w-px h-6 bg-slate-300 mx-1"></div>
        <button onClick={() => execCommand('insertUnorderedList')} className="p-2 hover:bg-slate-200 rounded" title="Llista"><i className="fas fa-list-ul"></i></button>
        <button onClick={() => execCommand('formatBlock', 'h3')} className="p-2 hover:bg-slate-200 rounded font-bold" title="Títol">H</button>
        <div className="w-px h-6 bg-slate-300 mx-1"></div>
        <button onClick={() => execCommand('removeFormat')} className="p-2 hover:bg-slate-200 rounded" title="Neteja format"><i className="fas fa-eraser"></i></button>
      </div>
      <div
        ref={editorRef}
        contentEditable
        onInput={handleInput}
        className="p-4 min-h-[300px] outline-none prose prose-slate max-w-none"
        style={{ whiteSpace: 'pre-wrap' }}
      />
    </div>
  );
};

import React from 'react';
import { AppStep } from '../types';

interface StepIndicatorProps {
  currentStep: AppStep;
}

export const StepIndicator: React.FC<StepIndicatorProps> = ({ currentStep }) => {
  const steps = [
    { key: AppStep.INPUT, label: 'Dades', icon: 'fa-file-import' },
    { key: AppStep.CONCLUSIONS, label: 'Conclusions', icon: 'fa-brain' },
    { key: AppStep.ORIENTATIONS, label: 'Orientacions', icon: 'fa-compass' },
    { key: AppStep.FINALIZE, label: 'Finalitza', icon: 'fa-check-double' },
  ];

  const getStatus = (stepKey: AppStep) => {
    const order = [AppStep.INPUT, AppStep.CONCLUSIONS, AppStep.ORIENTATIONS, AppStep.FINALIZE];
    const currentIndex = order.indexOf(currentStep);
    const stepIndex = order.indexOf(stepKey);

    if (stepIndex < currentIndex) return 'completed';
    if (stepIndex === currentIndex) return 'current';
    return 'pending';
  };

  return (
    <div className="flex items-center justify-between w-full max-w-3xl mx-auto mb-8 no-print">
      {steps.map((step, index) => {
        const status = getStatus(step.key);
        return (
          <React.Fragment key={step.key}>
            <div className="flex flex-col items-center group relative">
              <div className={`
                w-10 h-10 rounded-full flex items-center justify-center transition-all duration-300
                ${status === 'completed' ? 'bg-blue-600 text-white' : 
                  status === 'current' ? 'bg-blue-100 text-blue-600 ring-4 ring-blue-50' : 
                  'bg-white text-slate-400 border border-slate-200'}
              `}>
                <i className={`fas ${status === 'completed' ? 'fa-check' : step.icon}`}></i>
              </div>
              <span className={`mt-2 text-xs font-medium ${status === 'current' ? 'text-blue-600' : 'text-slate-500'}`}>
                {step.label}
              </span>
            </div>
            {index < steps.length - 1 && (
              <div className="flex-1 h-px bg-slate-200 mx-4 -mt-6"></div>
            )}
          </React.Fragment>
        );
      })}
    </div>
  );
};

import React, { useState, useCallback } from 'react';
import { AppStep, ReportData } from './types';
import { BLOCK_OPTIONS } from './constants';
import { geminiService } from './services/geminiService';
import { StepIndicator } from './components/StepIndicator';
import { RichTextEditor } from './components/RichTextEditor';

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.INPUT);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [report, setReport] = useState<ReportData>({
    rawInput: '',
    selectedBlocks: [5], // Default block 5 selected
    conclusions: '',
    orientations: '',
    studentName: '',
    schoolYear: new Date().getFullYear().toString() + '-' + (new Date().getFullYear() + 1).toString().slice(-2)
  });

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    try {
      const text = await file.text();
      setReport(prev => ({ ...prev, rawInput: prev.rawInput + '\n' + text }));
    } catch (err) {
      setError("No s'ha pogut llegir el fitxer. Assegura't que sigui un fitxer de text.");
    } finally {
      setLoading(false);
    }
  };

  const toggleBlock = (id: number) => {
    setReport(prev => {
      const blocks = prev.selectedBlocks.includes(id)
        ? prev.selectedBlocks.filter(b => b !== id)
        : [...prev.selectedBlocks, id];
      return { ...prev, selectedBlocks: blocks };
    });
  };

  const generateApartat1 = async () => {
    if (!report.rawInput.trim()) {
      setError("Si us plau, introdueix dades o notes de l'alumne.");
      return;
    }
    if (report.selectedBlocks.length === 0) {
      setError("Selecciona almenys un bloc per a l'informe.");
      return;
    }

    setLoading(true);
    setError(null);
    try {
      const result = await geminiService.generateConclusions(report.rawInput, report.selectedBlocks);
      setReport(prev => ({ ...prev, conclusions: result }));
      setStep(AppStep.CONCLUSIONS);
    } catch (err) {
      setError("Error en connectar amb la IA. Torna-ho a provar.");
    } finally {
      setLoading(false);
    }
  };

  const generateApartat2 = async () => {
    setLoading(true);
    setError(null);
    try {
      const result = await geminiService.generateOrientations(report.conclusions);
      setReport(prev => ({ ...prev, orientations: result }));
      setStep(AppStep.ORIENTATIONS);
    } catch (err) {
      setError("Error generant les orientacions.");
    } finally {
      setLoading(false);
    }
  };

  const reset = () => {
    if (confirm("Segur que vols començar un nou informe? Es perdran les dades actuals.")) {
      setReport({
        rawInput: '',
        selectedBlocks: [5],
        conclusions: '',
        orientations: '',
        studentName: '',
        schoolYear: new Date().getFullYear().toString() + '-' + (new Date().getFullYear() + 1).toString().slice(-2)
      });
      setStep(AppStep.INPUT);
      setError(null);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="min-h-screen py-8 px-4 sm:px-6 lg:px-8">
      {/* Header */}
      <header className="max-w-5xl mx-auto flex flex-col sm:flex-row items-center justify-between mb-8 no-print">
        <div className="flex items-center gap-3 mb-4 sm:mb-0">
          <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white text-2xl shadow-lg">
            <i className="fas fa-file-medical"></i>
          </div>
          <div>
            <h1 className="text-2xl font-bold text-slate-800">NESE Report Architect</h1>
            <p className="text-slate-500 text-sm">IA per a la redacció d'informes psicopedagògics</p>
          </div>
        </div>
        <button 
          onClick={reset}
          className="px-4 py-2 text-slate-500 hover:text-slate-800 transition-colors flex items-center gap-2 text-sm font-medium"
        >
          <i className="fas fa-redo"></i> Nou Informe
        </button>
      </header>

      {/* Main Content */}
      <main className="max-w-5xl mx-auto">
        <StepIndicator currentStep={step} />

        {error && (
          <div className="mb-6 p-4 bg-red-50 border-l-4 border-red-500 text-red-700 flex items-center gap-3 animate-pulse">
            <i className="fas fa-exclamation-circle"></i>
            <span>{error}</span>
            <button onClick={() => setError(null)} className="ml-auto text-red-400 hover:text-red-600">
              <i className="fas fa-times"></i>
            </button>
          </div>
        )}

        {/* STEP 1: INPUT */}
        {step === AppStep.INPUT && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 space-y-6">
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
                <div className="flex items-center justify-between mb-4">
                  <h2 className="text-lg font-bold flex items-center gap-2">
                    <i className="fas fa-pencil-alt text-blue-600"></i>
                    Dades de l'alumne i observacions
                  </h2>
                  <div className="flex items-center gap-2">
                     <label className="cursor-pointer bg-slate-100 hover:bg-slate-200 px-3 py-1.5 rounded-lg text-sm font-medium transition-colors flex items-center gap-2">
                        <i className="fas fa-upload text-slate-500"></i>
                        <span>Pujar .txt</span>
                        <input type="file" accept=".txt" onChange={handleFileUpload} className="hidden" />
                     </label>
                  </div>
                </div>
                <textarea
                  value={report.rawInput}
                  onChange={(e) => setReport(prev => ({ ...prev, rawInput: e.target.value }))}
                  placeholder="Enganxa aquí els informes mèdics, notes d'observació de l'EAP, transcripcions de reunions amb la família, etc..."
                  className="w-full h-80 p-4 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none resize-none bg-slate-50"
                />
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Nom de l'alumne</label>
                  <input 
                    type="text" 
                    value={report.studentName}
                    onChange={(e) => setReport(prev => ({ ...prev, studentName: e.target.value }))}
                    className="w-full px-3 py-2 border border-slate-200 rounded-lg outline-none focus:border-blue-500"
                    placeholder="Ex: Joan P."
                  />
                </div>
                <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Curs Escolar</label>
                  <input 
                    type="text" 
                    value={report.schoolYear}
                    onChange={(e) => setReport(prev => ({ ...prev, schoolYear: e.target.value }))}
                    className="w-full px-3 py-2 border border-slate-200 rounded-lg outline-none focus:border-blue-500"
                    placeholder="Ex: 2024-25"
                  />
                </div>
              </div>
            </div>

            <div className="space-y-6">
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
                <h2 className="text-lg font-bold mb-4 flex items-center gap-2">
                  <i className="fas fa-layer-group text-blue-600"></i>
                  Blocs a incloure
                </h2>
                <p className="text-sm text-slate-500 mb-6 italic">Quins apartats vols que l'IA analitzi i redacti en les conclusions?</p>
                <div className="space-y-3">
                  {BLOCK_OPTIONS.map((block) => (
                    <button
                      key={block.id}
                      onClick={() => toggleBlock(block.id)}
                      className={`
                        w-full text-left p-4 rounded-xl border transition-all duration-200 group
                        ${report.selectedBlocks.includes(block.id) 
                          ? 'border-blue-500 bg-blue-50' 
                          : 'border-slate-200 hover:border-slate-300 bg-white'}
                      `}
                    >
                      <div className="flex items-center justify-between mb-1">
                        <span className={`font-bold text-sm ${report.selectedBlocks.includes(block.id) ? 'text-blue-700' : 'text-slate-700'}`}>
                          {block.id}. {block.label}
                        </span>
                        <div className={`
                          w-5 h-5 rounded-full border flex items-center justify-center
                          ${report.selectedBlocks.includes(block.id) ? 'bg-blue-600 border-blue-600 text-white' : 'border-slate-300'}
                        `}>
                          {report.selectedBlocks.includes(block.id) && <i className="fas fa-check text-[10px]"></i>}
                        </div>
                      </div>
                      <p className="text-xs text-slate-500 leading-relaxed">{block.description}</p>
                    </button>
                  ))}
                </div>
              </div>

              <button
                onClick={generateApartat1}
                disabled={loading || !report.rawInput.trim()}
                className="w-full py-4 bg-blue-600 text-white rounded-2xl font-bold shadow-lg shadow-blue-200 hover:bg-blue-700 transition-all flex items-center justify-center gap-3 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {loading ? <i className="fas fa-circle-notch fa-spin"></i> : <i className="fas fa-wand-magic-sparkles"></i>}
                Generar Apartat 1
              </button>
            </div>
          </div>
        )}

        {/* STEP 2: CONCLUSIONS */}
        {step === AppStep.CONCLUSIONS && (
          <div className="space-y-8 animate-fadeIn">
            <div className="flex items-center justify-between no-print">
               <button onClick={() => setStep(AppStep.INPUT)} className="text-slate-500 hover:text-slate-800 font-medium flex items-center gap-2">
                 <i className="fas fa-arrow-left"></i> Enrere
               </button>
               <h2 className="text-xl font-bold text-slate-800">Apartat 1: Conclusions</h2>
               <div className="flex gap-3">
                 <button onClick={generateApartat2} disabled={loading} className="px-6 py-2 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 flex items-center gap-2">
                   {loading ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-lightbulb"></i>}
                   Generar Orientacions
                 </button>
               </div>
            </div>

            <RichTextEditor 
              label="APARTAT 1: CONCLUSIONS DE L'AVALUACIÓ PSICOPEDAGÒGICA"
              value={report.conclusions}
              onChange={(val) => setReport(prev => ({ ...prev, conclusions: val }))}
              className="shadow-xl"
            />
          </div>
        )}

        {/* STEP 3: ORIENTATIONS */}
        {step === AppStep.ORIENTATIONS && (
          <div className="space-y-8 animate-fadeIn">
            <div className="flex items-center justify-between no-print">
               <button onClick={() => setStep(AppStep.CONCLUSIONS)} className="text-slate-500 hover:text-slate-800 font-medium flex items-center gap-2">
                 <i className="fas fa-arrow-left"></i> Enrere
               </button>
               <h2 className="text-xl font-bold text-slate-800">Apartat 2: Orientacions</h2>
               <button onClick={() => setStep(AppStep.FINALIZE)} className="px-6 py-2 bg-green-600 text-white rounded-xl font-bold hover:bg-green-700 flex items-center gap-2">
                 <i className="fas fa-file-check"></i> Revisió Final
               </button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="opacity-60 pointer-events-none no-print">
                <RichTextEditor 
                  label="Apartat 1 (Lectura)"
                  value={report.conclusions}
                  onChange={() => {}}
                />
              </div>
              <RichTextEditor 
                label="APARTAT 2: ORIENTACIONS PER A L'ATENCIÓ EDUCATIVA"
                value={report.orientations}
                onChange={(val) => setReport(prev => ({ ...prev, orientations: val }))}
                className="shadow-xl ring-2 ring-blue-500"
              />
            </div>
          </div>
        )}

        {/* STEP 4: FINALIZE */}
        {step === AppStep.FINALIZE && (
          <div className="space-y-8 animate-fadeIn">
            <div className="flex items-center justify-between no-print">
               <button onClick={() => setStep(AppStep.ORIENTATIONS)} className="text-slate-500 hover:text-slate-800 font-medium flex items-center gap-2">
                 <i className="fas fa-arrow-left"></i> Editar
               </button>
               <div className="flex gap-4">
                 <button onClick={handlePrint} className="px-6 py-2 bg-slate-800 text-white rounded-xl font-bold hover:bg-slate-900 flex items-center gap-2">
                   <i className="fas fa-print"></i> Imprimir o Guardar PDF
                 </button>
               </div>
            </div>

            <div className="bg-white p-12 rounded-lg shadow-2xl border border-slate-200 report-container">
              {/* Report Letterhead */}
              <div className="border-b-2 border-slate-800 pb-6 mb-8 flex justify-between items-start">
                <div>
                  <h1 className="text-2xl font-black uppercase text-slate-800 tracking-tighter">Informe NESE</h1>
                  <p className="text-sm font-bold text-slate-600">Reconeixement de Necessitats Específiques de Suport Educatiu</p>
                </div>
                <div className="text-right text-xs text-slate-500 space-y-1">
                  <p><strong>ALUMNE:</strong> {report.studentName || '—'}</p>
                  <p><strong>CURS:</strong> {report.schoolYear}</p>
                  <p><strong>DATA:</strong> {new Date().toLocaleDateString('ca-ES')}</p>
                </div>
              </div>

              {/* Apartat 1 */}
              <section className="mb-12">
                <h2 className="text-lg font-black text-blue-900 border-l-4 border-blue-900 pl-4 mb-6 uppercase tracking-wide">
                  1. Conclusions de l'avaluació psicopedagògica
                </h2>
                <div className="prose prose-slate max-w-none text-justify leading-relaxed" dangerouslySetInnerHTML={{ __html: report.conclusions }} />
              </section>

              {/* Apartat 2 */}
              <section className="mb-12">
                <h2 className="text-lg font-black text-blue-900 border-l-4 border-blue-900 pl-4 mb-6 uppercase tracking-wide">
                  2. Orientacions per a l'atenció educativa de l'alumne
                </h2>
                <div className="prose prose-slate max-w-none text-justify leading-relaxed" dangerouslySetInnerHTML={{ __html: report.orientations }} />
              </section>

              {/* Footer / Signatures */}
              <div className="mt-20 pt-10 border-t border-slate-100 grid grid-cols-2 gap-20">
                <div className="border-t border-slate-300 pt-2 text-center text-xs text-slate-400">
                  Equip d'Assessorament i Orientació (EAP)
                </div>
                <div className="border-t border-slate-300 pt-2 text-center text-xs text-slate-400">
                  Signatura del Professional
                </div>
              </div>
            </div>

            <div className="bg-blue-50 p-6 rounded-2xl border border-blue-100 flex items-start gap-4 no-print">
              <i className="fas fa-info-circle text-blue-500 mt-1"></i>
              <div>
                <h3 className="font-bold text-blue-900">Recordatori de Privacitat</h3>
                <p className="text-sm text-blue-700">Aquesta eina processa les dades de manera temporal per generar l'informe. Un cop tinguis el document final, assegura't de guardar-lo seguint els protocols de seguretat de dades del teu centre o servei educatiu.</p>
              </div>
            </div>
          </div>
        )}
      </main>

      {/* Footer */}
      <footer className="mt-20 pb-10 text-center text-slate-400 text-sm no-print">
        <p>© {new Date().getFullYear()} NESE Report Architect — Basat en el Decret 150/2017</p>
      </footer>
    </div>
  );
};

