        <div className="flex items-center gap-3 mb-4 sm:mb-0">
          <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white text-2xl shadow-lg">
            <i className="fas fa-file-medical"></i>
          </div>
          <div>
            <h1 className="text-2xl font-bold text-slate-800">Elaboració de NESE</h1>
            <p className="text-slate-500 text-sm">IA per a la redacció d'informes psicopedagògics</p>
          </div>
        </div>
        <button 
          onClick={reset}
          className="px-4 py-2 text-slate-500 hover:text-slate-800 transition-colors flex items-center gap-2 text-sm font-medium"
        >
          <i className="fas fa-redo"></i> Nou Informe
        </button>
      </header>

      {/* Main Content */}
      <main className="max-w-5xl mx-auto">
        <StepIndicator currentStep={step} />

        {error && (
          <div className="mb-6 p-4 bg-red-50 border-l-4 border-red-500 text-red-700 flex items-center justify-between animate-fadeIn">
            <div className="flex items-center gap-3">
              <i className="fas fa-exclamation-circle text-xl"></i>
              <span>{error}</span>
            </div>
            <button onClick={() => setError(null)} className="text-red-400 hover:text-red-600">
              <i className="fas fa-times"></i>
            </button>
          </div>
        )}

        {/* STEP 1: INPUT */}
        {step === AppStep.INPUT && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 space-y-6">
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-4">
                  <h2 className="text-lg font-bold flex items-center gap-2">
                    <i className="fas fa-pencil-alt text-blue-600"></i>
                    Dades de l'alumne i observacions
                  </h2>
                  <div className="flex items-center gap-2">
                     <label className={`
                        cursor-pointer px-4 py-2 rounded-xl text-sm font-bold transition-all flex items-center gap-2 shadow-sm
                        ${fileProcessing ? 'bg-slate-100 text-slate-400 cursor-not-allowed' : 'bg-blue-50 text-blue-600 hover:bg-blue-100'}
                     `}>
                        {fileProcessing ? (
                          <i className="fas fa-circle-notch fa-spin"></i>
                        ) : (
                          <i className="fas fa-file-upload"></i>
                        )}
                        <span>{fileProcessing ? 'Processant...' : 'Adjuntar fitxer'}</span>
                        <input 
                          type="file" 
                          accept=".txt,.pdf,.docx,.xlsx,.xls" 
                          onChange={handleFileUpload} 
                          disabled={fileProcessing}
                          className="hidden" 
                        />
                     </label>
                  </div>
                </div>
                <div className="relative">
                  <textarea
                    value={report.rawInput}
                    onChange={(e) => setReport(prev => ({ ...prev, rawInput: e.target.value }))}
                    placeholder="Enganxa aquí informació o puja documents (PDF, Word, Excel, Text) per analitzar..."
                    className="w-full h-96 p-5 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-blue-100 focus:border-blue-400 outline-none resize-none bg-slate-50 transition-all leading-relaxed"
                  />
                  {report.rawInput && (
                    <button 
                      onClick={() => setReport(prev => ({ ...prev, rawInput: '' }))}
                      className="absolute bottom-4 right-4 text-xs font-bold text-red-500 hover:text-red-700 bg-white px-3 py-1.5 rounded-lg border border-red-100 shadow-sm transition-all"
                    >
                      <i className="fas fa-trash-alt mr-1"></i> Buidar text
                    </button>
                  )}
                </div>
                <div className="mt-4 flex flex-wrap gap-2">
                  <span className="text-[10px] font-bold uppercase text-slate-400">Formats suportats:</span>
                  <span className="px-2 py-0.5 bg-slate-100 text-slate-500 rounded text-[10px] font-medium">.PDF</span>
                  <span className="px-2 py-0.5 bg-slate-100 text-slate-500 rounded text-[10px] font-medium">.DOCX</span>
                  <span className="px-2 py-0.5 bg-slate-100 text-slate-500 rounded text-[10px] font-medium">.XLSX</span>
                  <span className="px-2 py-0.5 bg-slate-100 text-slate-500 rounded text-[10px] font-medium">.TXT</span>
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Nom de l'alumne</label>
                  <input 
                    type="text" 
                    value={report.studentName}
                    onChange={(e) => setReport(prev => ({ ...prev, studentName: e.target.value }))}
                    className="w-full px-3 py-2 border border-slate-200 rounded-lg outline-none focus:border-blue-500"
                    placeholder="Ex: Joan P."
                  />
                </div>
                <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Nivell Escolar</label>
                  <select 
                    value={report.schoolLevel}
                    onChange={(e) => setReport(prev => ({ ...prev, schoolLevel: e.target.value }))}
                    className="w-full px-3 py-2 border border-slate-200 rounded-lg outline-none focus:border-blue-500 bg-white"
                  >
                    {SCHOOL_LEVELS.map(level => (
                      <option key={level} value={level}>{level}</option>
                    ))}
                  </select>
                </div>
                <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Curs Escolar</label>
                  <input 
