                label="APARTAT 2: ORIENTACIONS PER A L'ATENCIÓ EDUCATIVA"
                value={report.orientations}
                onChange={(val) => setReport(prev => ({ ...prev, orientations: val }))}
                className="shadow-xl ring-2 ring-blue-500"
              />
