                </div>
                <div className="mt-4 flex flex-wrap gap-2">
                  <span className="text-[10px] font-bold uppercase text-slate-400">Formats suportats:</span>
                  <span className="px-2 py-0.5 bg-slate-100 text-slate-500 rounded text-[10px] font-medium">.PDF</span>
                  <span className="px-2 py-0.5 bg-slate-100 text-slate-500 rounded text-[10px] font-medium">.DOCX</span>
                  <span className="px-2 py-0.5 bg-slate-100 text-slate-500 rounded text-[10px] font-medium">.XLSX</span>
                  <span className="px-2 py-0.5 bg-slate-100 text-slate-500 rounded text-[10px] font-medium">.TXT</span>
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Nom de l'alumne</label>
                  <input 
                    type="text" 
                    value={report.studentName}
                    onChange={(e) => setReport(prev => ({ ...prev, studentName: e.target.value }))}
                    className="w-full px-3 py-2 border border-slate-200 rounded-lg outline-none focus:border-blue-500"
                    placeholder="Ex: Joan P."
                  />
                </div>
                <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Nivell Escolar</label>
                  <select 
                    value={report.schoolLevel}
                    onChange={(e) => setReport(prev => ({ ...prev, schoolLevel: e.target.value }))}
                    className="w-full px-3 py-2 border border-slate-200 rounded-lg outline-none focus:border-blue-500 bg-white"
                  >
                    {SCHOOL_LEVELS.map(level => (
                      <option key={level} value={level}>{level}</option>
                    ))}
                  </select>
                </div>
                <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Curs Escolar</label>
                  <input 
                    type="text" 
                    value={report.schoolYear}
                    onChange={(e) => setReport(prev => ({ ...prev, schoolYear: e.target.value }))}
                    className="w-full px-3 py-2 border border-slate-200 rounded-lg outline-none focus:border-blue-500"
                    placeholder="Ex: 2024-25"
                  />
                </div>
              </div>
            </div>

            <div className="space-y-6">
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
                <h2 className="text-lg font-bold mb-4 flex items-center gap-2">
                  <i className="fas fa-layer-group text-blue-600"></i>
                  Blocs a incloure
                </h2>
                <p className="text-sm text-slate-500 mb-6 italic">Quins apartats vols que l'IA analitzi i redacti en les conclusions?</p>
                <div className="space-y-3">
                  {BLOCK_OPTIONS.map((block) => (
                    <button
                      key={block.id}
                      onClick={() => toggleBlock(block.id)}
                      className={`
                        w-full text-left p-4 rounded-xl border transition-all duration-200 group
                        ${report.selectedBlocks.includes(block.id) 
                          ? 'border-blue-500 bg-blue-50' 
                          : 'border-slate-200 hover:border-slate-300 bg-white'}
                      `}
                    >
                      <div className="flex items-center justify-between mb-1">
                        <span className={`font-bold text-sm ${report.selectedBlocks.includes(block.id) ? 'text-blue-700' : 'text-slate-700'}`}>
                          {block.id}. {block.label}
                        </span>
                        <div className={`
                          w-5 h-5 rounded-full border flex items-center justify-center
                          ${report.selectedBlocks.includes(block.id) ? 'bg-blue-600 border-blue-600 text-white' : 'border-slate-300'}
                        `}>
                          {report.selectedBlocks.includes(block.id) && <i className="fas fa-check text-[10px]"></i>}
                        </div>
                      </div>
                      <p className="text-xs text-slate-500 leading-relaxed">{block.description}</p>
                    </button>
                  ))}
                </div>
              </div>

              <button
                onClick={generateApartat1}
                disabled={loading || !report.rawInput.trim() || fileProcessing}
                className="w-full py-4 bg-blue-600 text-white rounded-2xl font-bold shadow-lg shadow-blue-200 hover:bg-blue-700 transition-all flex items-center justify-center gap-3 disabled:opacity-50 disabled:cursor-not-allowed"
              >
