               </button>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="opacity-60 pointer-events-none no-print"><RichTextEditor label="Apartat 1 (Lectura)" value={report.conclusions} onChange={() => {}} /></div>
              <RichTextEditor label="ORIENTACIONS" value={report.orientations} onChange={(val) => setReport(prev => ({ ...prev, orientations: val }))} className="shadow-xl ring-2 ring-blue-500" />
            </div>
          </div>
        )}

        {/* STEP 4: FINALIZE */}
        {step === AppStep.FINALIZE && (
          <div className="space-y-8 animate-fadeIn">
            <div className="flex items-center justify-between no-print">
               <button onClick={() => { setStep(AppStep.ORIENTATIONS); setReport(p => ({...p, currentStep: AppStep.ORIENTATIONS})); }} className="text-slate-500 hover:text-slate-800 font-medium flex items-center gap-2"><i className="fas fa-arrow-left"></i> Editar</button>
               <div className="flex flex-wrap gap-4">
                 <button onClick={() => saveReportToHistory()} className="px-6 py-2 bg-indigo-600 text-white rounded-xl font-bold hover:bg-indigo-700 flex items-center gap-2 shadow-lg transition-all">
                   <i className="fas fa-save"></i> Guardar Historial
                 </button>
                 <button onClick={handleDownloadWord} className="px-6 py-2 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 flex items-center gap-2 shadow-lg transition-all">
                   <i className="fas fa-file-word"></i> Guardar (.doc)
                 </button>
                 <button onClick={handlePrint} className="px-6 py-2 bg-slate-800 text-white rounded-xl font-bold hover:bg-slate-900 flex items-center gap-2 shadow-lg transition-all">
                   <i className="fas fa-print"></i> Imprimir / PDF
                 </button>
               </div>
            </div>

            <div className="bg-white p-12 rounded-lg shadow-2xl border border-slate-200 report-container">
              <div className="border-b-2 border-slate-800 pb-6 mb-8 flex justify-between items-start">
                <div>
                  <h1 className="text-2xl font-black uppercase text-slate-800 tracking-tighter">Informe NESE</h1>
                  <p className="text-sm font-bold text-slate-600">Reconeixement de Necessitats Específiques de Suport Educatiu</p>
                </div>
                <div className="text-right text-xs text-slate-500 space-y-1">
                  <p><strong>ALUMNE:</strong> {report.studentName || '—'}</p>
                  <p><strong>NIVELL:</strong> {report.schoolLevel || '—'}</p>
                  <p><strong>CURS:</strong> {report.schoolYear || '—'}</p>
                  <p><strong>DATA:</strong> {new Date(report.timestamp || Date.now()).toLocaleDateString('ca-ES')}</p>
                </div>
              </div>
              <section className="mb-12">
                <h2 className="text-lg font-black text-blue-900 border-l-4 border-blue-900 pl-4 mb-6 uppercase tracking-wide">1. Conclusions de l'avaluació psicopedagògica</h2>
                <div className="prose prose-slate max-w-none text-justify leading-relaxed" dangerouslySetInnerHTML={{ __html: report.conclusions }} />
              </section>
              <section className="mb-12">
                <h2 className="text-lg font-black text-blue-900 border-l-4 border-blue-900 pl-4 mb-6 uppercase tracking-wide">2. Orientacions per a l'atenció educativa</h2>
                <div className="prose prose-slate max-w-none text-justify leading-relaxed" dangerouslySetInnerHTML={{ __html: report.orientations }} />
              </section>
              <div className="mt-20 pt-10 border-t border-slate-100 grid grid-cols-2 gap-20">
                <div className="border-t border-slate-300 pt-2 text-center text-xs text-slate-400">Equip d'Assessorament i Orientació (EAP)</div>
                <div className="border-t border-slate-300 pt-2 text-center text-xs text-slate-400">Signatura del Professional</div>
              </div>
            </div>
          </div>
        )}
      </main>

      <footer className="mt-20 pb-10 text-center text-slate-400 text-sm no-print">
        <p>© {new Date().getFullYear()} Elaboració de NESE — Basat en el Decret 150/2017</p>
      </footer>
    </div>
  );
};

export default App;

import { GoogleGenAI } from "@google/genai";
import { SYSTEM_PROMPT_PART_1, SYSTEM_PROMPT_PART_2 } from "../constants";

export class GeminiService {
  private getApiKey(): string {
    try {
      // @ts-ignore
      const apiKey = process?.env?.API_KEY || window?.process?.env?.API_KEY || "";
      return apiKey;
    } catch (e) {
      return "";
    }
  }

  async generateConclusions(input: string, selectedBlocks: number[], level?: string): Promise<string> {
    const apiKey = this.getApiKey();
    if (!apiKey) return "Error: API_KEY no configurada a l'entorn.";

    const ai = new GoogleGenAI({ apiKey });
    const blocksText = selectedBlocks.join(", ");
    const levelContext = level ? `L'alumne es troba al nivell de: ${level}.` : '';
    const prompt = `CONTEXT DE L'ALUMNE:
${levelContext}

INFORMACIÓ PROPORCIONADA:
${input}

INSTRUCCIÓ:
L'usuari ha seleccionat els següents blocs per incloure en l'informe: ${blocksText}. 
Redacta l'apartat 1 de l'informe seguint estrictament les instruccions del teu rol.`;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: {
          systemInstruction: SYSTEM_PROMPT_PART_1,
          temperature: 0.7,
        },
      });

      return response.text || "No s'ha obtingut resposta de la IA.";
    } catch (err: any) {
      console.error("Error Gemini:", err);
      return `Error en la generació: ${err.message || 'Error desconegut'}`;
    }
  }

  async generateOrientations(conclusions: string, level?: string): Promise<string> {
    const apiKey = this.getApiKey();
    if (!apiKey) return "Error: API_KEY no configurada.";

    const ai = new GoogleGenAI({ apiKey });
    const levelContext = level ? `Nota: L'alumne és de nivell ${level}.` : '';
    const prompt = `${levelContext}\n\nBasant-te en les següents conclusions de l'apartat 1, redacta l'apartat 2 d'orientacions:\n\n${conclusions}`;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: {
          systemInstruction: SYSTEM_PROMPT_PART_2,
          temperature: 0.7,
        },
      });

      return response.text || "No s'ha obtingut resposta de la IA.";
    } catch (err: any) {
      console.error("Error Gemini:", err);
      return `Error en la generació: ${err.message || 'Error desconegut'}`;
    }
  }
}

export const geminiService = new GeminiService();

import React, { useState, useEffect, useRef } from 'react';
import { AppStep, ReportData } from './types';
import { BLOCK_OPTIONS, SCHOOL_LEVELS } from './constants';
import { geminiService } from './services/geminiService';
import { fileService } from './services/fileService';
import { StepIndicator } from './components/StepIndicator';
import { RichTextEditor } from './components/RichTextEditor';

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.INPUT);
  const [loading, setLoading] = useState(false);
  const [fileProcessing, setFileProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showHistory, setShowHistory] = useState(false);
  const [savedReports, setSavedReports] = useState<ReportData[]>([]);

  const initialReportState: ReportData = {
    rawInput: '',
    selectedBlocks: [],
    conclusions: '',
    orientations: '',
    studentName: '',
    schoolYear: '', 
    schoolLevel: '', 
    currentStep: AppStep.INPUT
  };

  const [report, setReport] = useState<ReportData>(initialReportState);
  const prevNameRef = useRef('');

  const getIntroTemplate = (name: string) => {
    const displayName = name.trim() || 'XXX';
    return `En l'avaluació psicopedagògica de ${displayName} observem diferents aspectes a tenir presents per oferir una resposta educativa davant d'unes necessitats específiques relacionades amb els següents àmbits:`;
  };

  useEffect(() => {
    const currentName = report.studentName;
    const oldTemplate = getIntroTemplate(prevNameRef.current);
    const newTemplate = getIntroTemplate(currentName);

    setReport(prev => {
      if (!prev.rawInput.trim() || prev.rawInput === oldTemplate || prev.rawInput === getIntroTemplate('')) {
        return { ...prev, rawInput: newTemplate };
      }
      if (prev.rawInput.startsWith(oldTemplate)) {
        return { ...prev, rawInput: prev.rawInput.replace(oldTemplate, newTemplate) };
      }
      return prev;
    });
    prevNameRef.current = currentName;
  }, [report.studentName]);

  useEffect(() => {
    const history = localStorage.getItem('nese_reports_history');
    if (history) {
      try {
        setSavedReports(JSON.parse(history));
      } catch (e) {
        console.error("Error history:", e);
      }
    }
  }, []);

  const saveToLocalStorage = (reports: ReportData[]) => {
    localStorage.setItem('nese_reports_history', JSON.stringify(reports));
    setSavedReports(reports);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setFileProcessing(true);
    setError(null);
    try {
      const text = await fileService.extractText(file);
      setReport(prev => ({ 
        ...prev, 
        rawInput: prev.rawInput + (prev.rawInput ? '\n\n' : '') + `[Fitxer: ${file.name}]:\n` + text 
      }));
    } catch (err: any) {
      setError(`Error: ${err.message || 'Error fitxer'}`);
    } finally {
      setFileProcessing(false);
      e.target.value = '';
    }
  };

  const toggleBlock = (id: number) => {
    setReport(prev => ({
      ...prev,
      selectedBlocks: prev.selectedBlocks.includes(id) 
        ? prev.selectedBlocks.filter(b => b !== id) 
        : [...prev.selectedBlocks, id]
    }));
  };

  const generateApartat1 = async () => {
    if (!report.rawInput.trim() || report.rawInput === getIntroTemplate(report.studentName)) {
      setError("Afegeix més informació després de la introducció.");
      return;
    }
    if (report.selectedBlocks.length === 0) {
      setError("Selecciona un bloc.");
      return;
    }
    setLoading(true);
    setError(null);
    try {
      const result = await geminiService.generateConclusions(report.rawInput, report.selectedBlocks, report.schoolLevel);
      setReport(prev => ({ ...prev, conclusions: result, currentStep: AppStep.CONCLUSIONS }));
      setStep(AppStep.CONCLUSIONS);
    } catch (err) {
      setError("Error IA.");
    } finally {
      setLoading(false);
    }
  };

  const generateApartat2 = async () => {
    setLoading(true);
    try {
      const result = await geminiService.generateOrientations(report.conclusions, report.schoolLevel);
      setReport(prev => ({ ...prev, orientations: result, currentStep: AppStep.ORIENTATIONS }));
      setStep(AppStep.ORIENTATIONS);
    } catch (err) {
      setError("Error IA.");
    } finally {
      setLoading(false);
    }
  };

  const saveReport = () => {
    const newReport = { ...report, id: report.id || Math.random().toString(36).substr(2, 9), timestamp: Date.now(), currentStep: step };
    const updated = report.id ? savedReports.map(r => r.id === report.id ? newReport : r) : [newReport, ...savedReports];
    saveToLocalStorage(updated);
    setReport(newReport);
    alert("Guardat.");
  };

  return (
    <div className="min-h-screen py-8 px-4 sm:px-6 lg:px-8">
      {showHistory && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[80vh]">
            <div className="p-6 border-b flex justify-between items-center bg-slate-50">
              <h2 className="text-xl font-bold">Historial</h2>
              <button onClick={() => setShowHistory(false)} className="w-8 h-8 rounded-full hover:bg-slate-200 flex items-center justify-center"><i className="fas fa-times"></i></button>
            </div>
            <div className="overflow-y-auto p-6 space-y-4">
              {savedReports.map(r => (
                <div key={r.id} onClick={() => { setReport(r); setStep(r.currentStep || AppStep.INPUT); setShowHistory(false); }} className="p-4 border border-slate-200 rounded-2xl hover:bg-blue-50 cursor-pointer flex justify-between items-center group">
                  <div>
                    <div className="font-bold">{r.studentName || 'Sense nom'}</div>
                    <div className="text-xs text-slate-500">{new Date(r.timestamp!).toLocaleDateString()}</div>
                  </div>
                  <button onClick={(e) => { e.stopPropagation(); saveToLocalStorage(savedReports.filter(x => x.id !== r.id)); }} className="opacity-0 group-hover:opacity-100 text-slate-400 hover:text-red-500"><i className="fas fa-trash"></i></button>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      <header className="max-w-5xl mx-auto flex flex-col sm:flex-row items-center justify-between mb-8 no-print">
