          <button onClick={() => setShowHistory(true)} className="px-5 py-2.5 text-slate-600 font-bold text-sm bg-white border border-slate-200 rounded-xl hover:bg-slate-50 transition-all">Historial</button>
          <button onClick={saveReportToHistory} disabled={!report.rawInput.trim() && !report.studentName} className="px-5 py-2.5 bg-indigo-600 text-white rounded-xl font-bold text-sm shadow-md hover:bg-indigo-700 disabled:opacity-40 transition-all">Guardar</button>
