export default App;

import React from 'react';
import { AppStep } from '../types';

interface StepIndicatorProps {
  currentStep: AppStep;
}

export const StepIndicator: React.FC<StepIndicatorProps> = ({ currentStep }) => {
  const steps = [
    { key: AppStep.INPUT, label: 'Dades', icon: 'fa-file-import' },
    { key: AppStep.CONCLUSIONS, label: 'Conclusions', icon: 'fa-brain' },
    { key: AppStep.ORIENTATIONS, label: 'Orientacions', icon: 'fa-compass' },
    { key: AppStep.FINALIZE, label: 'Finalitza', icon: 'fa-check-double' },
  ];

  const getStatus = (stepKey: AppStep) => {
    const order = [AppStep.INPUT, AppStep.CONCLUSIONS, AppStep.ORIENTATIONS, AppStep.FINALIZE];
    const currentIndex = order.indexOf(currentStep);
    const stepIndex = order.indexOf(stepKey);

    if (stepIndex < currentIndex) return 'completed';
    if (stepIndex === currentIndex) return 'current';
    return 'pending';
  };

  return (
    <div className="flex items-center justify-between w-full max-w-3xl mx-auto mb-8 no-print">
      {steps.map((step, index) => {
        const status = getStatus(step.key);
        return (
          <React.Fragment key={step.key}>
            <div className="flex flex-col items-center group relative">
              <div className={`
                w-10 h-10 rounded-full flex items-center justify-center transition-all duration-300
                ${status === 'completed' ? 'bg-emerald-700 text-white' : 
                  status === 'current' ? 'bg-emerald-100 text-emerald-700 ring-4 ring-emerald-50' : 
                  'bg-white text-slate-400 border border-slate-200'}
              `}>
                <i className={`fas ${status === 'completed' ? 'fa-check' : step.icon}`}></i>
              </div>
              <span className={`mt-2 text-xs font-medium ${status === 'current' ? 'text-emerald-700' : 'text-slate-500'}`}>
                {step.label}
              </span>
            </div>
            {index < steps.length - 1 && (
              <div className="flex-1 h-px bg-slate-200 mx-4 -mt-6"></div>
            )}
          </React.Fragment>
        );
      })}
    </div>
  );
};

import React, { useRef, useEffect } from 'react';

interface RichTextEditorProps {
  value: string;
  onChange: (value: string) => void;
  className?: string;
  label?: string;
}

export const RichTextEditor: React.FC<RichTextEditorProps> = ({ value, onChange, className = '', label }) => {
  const editorRef = useRef<HTMLDivElement>(null);
  const isFocused = useRef(false);

  useEffect(() => {
    if (editorRef.current && !isFocused.current && editorRef.current.innerHTML !== value) {
      editorRef.current.innerHTML = value;
    }
  }, [value]);

  const handleInput = () => {
    if (editorRef.current) {
      onChange(editorRef.current.innerHTML);
    }
  };

  const execCommand = (command: string, val: string = '') => {
    document.execCommand(command, false, val);
    handleInput();
  };

  return (
    <div className={`flex flex-col border border-slate-200 rounded-2xl bg-white overflow-hidden shadow-sm ${className}`}>
      {label && (
        <div className="px-4 py-2 text-xs font-bold text-slate-500 bg-slate-50 border-b flex justify-between items-center">
          <span>{label}</span>
          <span className="text-[10px] font-normal text-slate-400 italic">Pots editar aquest text directament</span>
        </div>
      )}
      <div className="flex items-center gap-1 p-2 border-b bg-slate-50 no-print">
        <button onClick={() => execCommand('bold')} className="p-2 hover:bg-emerald-100 rounded text-slate-700" title="Negreta"><i className="fas fa-bold"></i></button>
        <button onClick={() => execCommand('italic')} className="p-2 hover:bg-emerald-100 rounded text-slate-700" title="Cursiva"><i className="fas fa-italic"></i></button>
        <div className="w-px h-6 bg-slate-300 mx-1"></div>
        <button onClick={() => execCommand('insertUnorderedList')} className="p-2 hover:bg-emerald-100 rounded text-slate-700" title="Llista"><i className="fas fa-list-ul"></i></button>
        <button onClick={() => execCommand('formatBlock', 'h3')} className="p-2 hover:bg-emerald-100 rounded font-bold text-slate-700" title="Títol">H</button>
        <div className="w-px h-6 bg-slate-300 mx-1"></div>
        <button onClick={() => execCommand('removeFormat')} className="p-2 hover:bg-emerald-100 rounded text-slate-700" title="Neteja format"><i className="fas fa-eraser"></i></button>
      </div>
      <div
        ref={editorRef}
        contentEditable
        onInput={handleInput}
        onFocus={() => { isFocused.current = true; }}
        onBlur={() => { isFocused.current = false; }}
        className="p-6 min-h-[400px] outline-none prose prose-slate max-w-none focus:ring-2 focus:ring-emerald-100 transition-all"
        style={{ whiteSpace: 'pre-wrap' }}
      />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { AppStep, ReportData } from './types';
import { BLOCK_OPTIONS, SCHOOL_LEVELS } from './constants';
import { geminiService } from './services/geminiService';
import { fileService } from './services/fileService';
import { StepIndicator } from './components/StepIndicator';
import { RichTextEditor } from './components/RichTextEditor';

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.INPUT);
  const [loading, setLoading] = useState(false);
  const [fileProcessing, setFileProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showHistory, setShowHistory] = useState(false);
  const [savedReports, setSavedReports] = useState<ReportData[]>([]);

  const initialReportState: ReportData = {
    rawInput: '',
    selectedBlocks: [],
    conclusions: '',
    orientations: '',
    studentName: '',
    schoolYear: '', 
    schoolLevel: '', 
    currentStep: AppStep.INPUT
  };

  const [report, setReport] = useState<ReportData>(initialReportState);

  useEffect(() => {
    const history = localStorage.getItem('nese_reports_history');
    if (history) {
      try {
        setSavedReports(JSON.parse(history));
      } catch (e) {
        console.error("Error carregant historial", e);
      }
    }
  }, []);

  const saveToLocalStorage = (reports: ReportData[]) => {
    localStorage.setItem('nese_reports_history', JSON.stringify(reports));
    setSavedReports(reports);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setFileProcessing(true);
    setError(null);
    try {
      const text = await fileService.extractText(file);
      setReport(prev => ({ 
        ...prev, 
        rawInput: prev.rawInput + (prev.rawInput ? '\n\n' : '') + `[Contingut de ${file.name}]:\n` + text 
      }));
    } catch (err: any) {
      setError(`Error en el fitxer: ${err.message || 'Error desconegut'}`);
    } finally {
      setFileProcessing(false);
      if (e.target) e.target.value = '';
    }
  };

  const toggleBlock = (id: number) => {
    setReport(prev => ({
      ...prev,
      selectedBlocks: prev.selectedBlocks.includes(id)
        ? prev.selectedBlocks.filter(b => b !== id)
        : [...prev.selectedBlocks, id]
    }));
  };

  const generateApartat1 = async () => {
    if (!report.rawInput.trim()) {
      setError("Si us plau, introdueix dades o notes de l'alumne a l'apartat d'observacions.");
      return;
    }
    if (report.selectedBlocks.length === 0) {
      setError("Selecciona almenys un dels blocs NESE superiors.");
      return;
    }
    setLoading(true);
    setError(null);
    try {
      const result = await geminiService.generateConclusions(report.rawInput, report.selectedBlocks, report.schoolLevel);
      setReport(prev => ({ ...prev, conclusions: result, currentStep: AppStep.CONCLUSIONS }));
      setStep(AppStep.CONCLUSIONS);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } catch (err: any) {
      setError(`Error de generació: ${err.message || 'No s\'ha pogut connectar amb la IA'}`);
    } finally {
      setLoading(false);
    }
  };

  const generateApartat2 = async () => {
    if (!report.conclusions || report.conclusions.trim().length < 20) {
      setError("Cal que hi hagi contingut a l'apartat de conclusions per poder generar les orientacions.");
      return;
    }
    setLoading(true);
    setError(null);
    try {
      const result = await geminiService.generateOrientations(report.conclusions, report.schoolLevel);
      setReport(prev => ({ ...prev, orientations: result, currentStep: AppStep.ORIENTATIONS }));
      setStep(AppStep.ORIENTATIONS);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } catch (err: any) {
      setError(`Error de generació d'orientacions: ${err.message || 'S\'ha produït un error inesperat'}`);
    } finally {
      setLoading(false);
    }
  };

  const saveReportToHistory = () => {
    const newReport = { 
      ...report, 
      id: report.id || Math.random().toString(36).substr(2, 9),
      timestamp: Date.now(),
      currentStep: step
    };
    const updatedHistory = report.id ? savedReports.map(r => r.id === report.id ? newReport : r) : [newReport, ...savedReports];
    saveToLocalStorage(updatedHistory);
    setReport(newReport);
    alert("Informe guardat a l'historial local.");
  };

  const reset = () => {
    if (confirm("Segur que vols iniciar un nou informe? Es perdran les dades no guardades.")) window.location.reload();
  };

  return (
    <div className="min-h-screen py-8 px-4 sm:px-6 lg:px-8 max-w-6xl mx-auto">
      {/* Historial Modal */}
      {showHistory && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[80vh]">
            <div className="p-6 border-b flex justify-between items-center bg-slate-50">
              <h2 className="text-xl font-bold text-slate-800">Historial d'informes</h2>
              <button onClick={() => setShowHistory(false)} className="p-2 text-slate-400 hover:text-slate-600"><i className="fas fa-times"></i></button>
            </div>
            <div className="overflow-y-auto p-6 space-y-4">
              {savedReports.length === 0 ? <p className="text-center text-slate-400 py-10">No hi ha informes guardats encara.</p> : 
                savedReports.map(r => (
                  <div key={r.id} onClick={() => { setReport(r); setStep(r.currentStep || AppStep.INPUT); setShowHistory(false); }} className="p-4 border border-slate-100 rounded-2xl hover:bg-emerald-50 hover:border-emerald-200 cursor-pointer flex justify-between items-center group transition-all">
                    <div>
                      <h4 className="font-bold text-slate-700">{r.studentName || 'Alumne sense nom'}</h4>
                      <p className="text-xs text-slate-500">{new Date(r.timestamp!).toLocaleString()}</p>
                    </div>
                    <button onClick={(e) => { e.stopPropagation(); if(confirm("Eliminar?")) saveToLocalStorage(savedReports.filter(x => x.id !== r.id)); }} className="opacity-0 group-hover:opacity-100 p-2 text-slate-300 hover:text-red-500 transition-all"><i className="fas fa-trash-alt"></i></button>
                  </div>
                ))
              }
            </div>
          </div>
        </div>
      )}

      {/* Header */}
      <header className="flex flex-col sm:flex-row items-center justify-between mb-10 no-print gap-4">
        <div className="flex items-center gap-4">
          <div className="w-14 h-14 bg-gradient-to-br from-emerald-700 to-teal-800 rounded-2xl flex items-center justify-center text-white text-3xl shadow-xl shadow-emerald-200"><i className="fas fa-file-medical"></i></div>
          <div>
            <h1 className="text-3xl font-extrabold text-slate-800 tracking-tight">Elaboració de NESE</h1>
            <p className="text-emerald-700 font-medium italic">Equip d'Orientació Psicopedagògica</p>
          </div>
        </div>
        <div className="flex gap-3">
          <button onClick={() => setShowHistory(true)} className="px-5 py-2.5 text-slate-600 font-bold text-sm bg-white border border-slate-200 rounded-xl hover:bg-slate-50 transition-all">Historial</button>
          <button onClick={saveReportToHistory} disabled={!report.rawInput.trim() && !report.studentName} className="px-5 py-2.5 bg-emerald-700 text-white rounded-xl font-bold text-sm shadow-md hover:bg-emerald-800 disabled:opacity-40 transition-all">Guardar</button>
          <button onClick={reset} className="px-5 py-2.5 bg-slate-100 text-slate-700 rounded-xl font-bold text-sm hover:bg-slate-200 transition-all">Nou</button>
        </div>
