  const reset = () => {
    if (confirm("Segur que vols iniciar un nou informe? Es perdran les dades no guardades.")) window.location.reload();
  };

  return (
    <div className="min-h-screen py-8 px-4 sm:px-6 lg:px-8 max-w-6xl mx-auto">
