              </div>

              {/* CONTINGUT DE L'INFORME */}
              <div className="space-y-24 report-content">
                <section>
                  <div className="mb-10">
                    <h2 className="text-2xl font-black uppercase text-emerald-900 m-0">1. Conclusions de l'Avaluació</h2>
                    <div className="w-24 h-1.5 bg-emerald-700 mt-2"></div>
                  </div>
                  <div className="text-slate-700 text-justify leading-relaxed text-sm sm:text-base prose-p:mb-6 prose-headings:font-black prose-headings:text-emerald-800 prose-headings:mt-12 prose-headings:mb-4 prose-hr:my-12 prose-hr:border-none prose-hr:h-12" dangerouslySetInnerHTML={{__html: report.conclusions}} />
                </section>

                <div className="page-break my-16"></div>

                <section>
                  <div className="mb-10">
                    <h2 className="text-2xl font-black uppercase text-teal-900 m-0">2. Orientacions per a la Resposta Educativa</h2>
                    <div className="w-24 h-1.5 bg-teal-700 mt-2"></div>
                  </div>
                  <div className="text-slate-700 text-justify leading-relaxed text-sm sm:text-base prose-p:mb-6 prose-headings:font-black prose-headings:text-teal-800 prose-headings:mt-12 prose-headings:mb-4 prose-li:mb-3 prose-hr:my-12 prose-hr:border-none prose-hr:h-12" dangerouslySetInnerHTML={{__html: report.orientations}} />
                </section>
              </div>

              <div className="mt-32 pt-12 border-t border-slate-100 flex justify-end">
                <div className="text-center w-64">
                  <div className="h-24 flex items-center justify-center italic text-slate-300 text-xs mb-2">Signatura Digital / Segell</div>
                  <hr className="border-emerald-200" />
