                Vista Prèvia Final <i className="fas fa-check-circle"></i>
              </button>
            </div>

            <RichTextEditor 
              label="APARTAT 2: ORIENTACIONS PER A LA RESPOSTA EDUCATIVA" 
              value={report.orientations} 
              onChange={v => setReport({...report, orientations: v})} 
