        </tr>
        <tr>
          <td><span class="label">Curs Escolar:</span><br/><span class="value">${report.schoolYear || 'N/A'}</span></td>
          <td><span class="label">Data:</span><br/><span class="value">${new Date().toLocaleDateString('ca-ES')}</span></td>
