  }

  return (
    <div className="min-h-screen py-8 px-4 sm:px-6 lg:px-8 max-w-6xl mx-auto pb-24">
      <style>{`
        .report-content { line-height: 1.5 !important; }
        .report-content p { margin-bottom: 1.5rem !important; text-align: justify; }
