              </h2>
              <div className="grid grid-cols-1 gap-3">
                {BLOCK_OPTIONS.map(block => (
                  <button 
                    key={block.id} 
                    onClick={() => toggleBlock(block.id)} 
                    className={`text-left p-5 rounded-2xl border-2 transition-all group ${report.selectedBlocks.includes(block.id) ? 'border-emerald-700 bg-emerald-50/50 ring-4 ring-emerald-50' : 'bg-white border-slate-100 hover:border-slate-300'}`}
                  >
                    <div className="flex items-center gap-3 mb-2">
                      <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-colors ${report.selectedBlocks.includes(block.id) ? 'bg-emerald-700 border-emerald-700 text-white' : 'border-slate-300'}`}>
                        {report.selectedBlocks.includes(block.id) && <i className="fas fa-check text-[10px]"></i>}
                      </div>
                      <span className="font-bold text-sm text-slate-700 leading-tight">{block.label}</span>
                    </div>
                    <p className="text-xs text-slate-500 leading-relaxed opacity-80 group-hover:opacity-100">{block.description}</p>
                  </button>
                ))}
              </div>
            </div>

            <div className="bg-white p-8 rounded-3xl border border-slate-100">
              <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4">
                <h2 className="text-xl font-bold flex items-center gap-3 text-slate-800">
                  <span className="w-8 h-8 bg-emerald-100 text-emerald-700 rounded-full flex items-center justify-center text-sm">2</span>
                  Observacions i Dades de l'Avaluació
                </h2>
                <div className="flex gap-2">
                  <label className="cursor-pointer px-5 py-2.5 bg-emerald-700 text-white rounded-xl text-sm font-bold hover:bg-emerald-800 transition-all flex items-center gap-2">
                    <i className="fas fa-cloud-upload-alt"></i>
                    {fileProcessing ? 'Llegint...' : 'Adjuntar Document'}
                    <input type="file" onChange={handleFileUpload} disabled={fileProcessing} className="hidden" />
                  </label>
                </div>
              </div>

              <div className="w-full">
                <textarea 
                  value={report.rawInput} 
                  onChange={e => setReport({...report, rawInput: e.target.value})} 
                  className="w-full h-96 p-6 border border-slate-200 rounded-3xl outline-none bg-slate-50 focus:bg-white focus:ring-4 focus:ring-emerald-50 transition-all resize-none text-slate-700 leading-relaxed" 
                  placeholder="Escriu o enganxa aquí les notes de l'avaluació..." 
                />
              </div>
            </div>

            <button 
              onClick={generateApartat1} 
              disabled={loading || !report.rawInput.trim() || report.selectedBlocks.length === 0} 
              className="w-full py-5 bg-gradient-to-r from-emerald-700 to-teal-800 text-white rounded-3xl font-extrabold hover:scale-[1.01] transition-all disabled:opacity-50 text-xl"
            >
              {loading ? <><i className="fas fa-circle-notch fa-spin mr-3"></i> Elaborant Conclusions...</> : "Generar conclusions de l'avaluació psicopedagògica"}
            </button>
          </div>
        )}

        {/* STEP 2: CONCLUSIONS */}
        {step === AppStep.CONCLUSIONS && (
          <div className="space-y-8 animate-fadeIn">
            <div className="flex justify-between items-center no-print">
              <button onClick={() => setStep(AppStep.INPUT)} className="text-slate-500 font-bold flex items-center gap-2 hover:text-emerald-800 transition-all group">
                <i className="fas fa-arrow-left group-hover:-translate-x-1 transition-transform"></i> Tornar a dades
              </button>
              <button 
                onClick={generateApartat2} 
                disabled={loading} 
                className="px-8 py-3 bg-emerald-700 text-white rounded-2xl font-bold hover:bg-emerald-800 transition-all flex items-center gap-3 disabled:opacity-50"
              >
                {loading ? <><i className="fas fa-spinner fa-spin"></i> Generant Orientacions...</> : <>Següent: Orientacions <i className="fas fa-arrow-right"></i></>}
              </button>
            </div>

            <RichTextEditor 
              label="CONCLUSIONS DE L'AVALUACIÓ" 
              value={report.conclusions} 
              onChange={v => setReport({...report, conclusions: v})} 
            />

            <div className="flex justify-center pt-6 no-print">
              <button 
                onClick={generateApartat2} 
                disabled={loading} 
                className="px-12 py-5 bg-emerald-700 text-white rounded-2xl font-black text-xl hover:bg-emerald-800 hover:scale-[1.02] transition-all flex items-center gap-4 disabled:opacity-50"
              >
                {loading ? <><i className="fas fa-circle-notch fa-spin"></i> Elaborant...</> : <>ELABORAR ORIENTACIONS <i className="fas fa-wand-magic-sparkles"></i></>}
              </button>
            </div>
          </div>
        )}

        {/* STEP 3: ORIENTATIONS */}
        {step === AppStep.ORIENTATIONS && (
          <div className="space-y-8 animate-fadeIn">
            <div className="flex justify-between items-center no-print">
              <button onClick={() => setStep(AppStep.CONCLUSIONS)} className="text-slate-500 font-bold flex items-center gap-2 hover:text-emerald-800 transition-all">
                <i className="fas fa-arrow-left"></i> Editar Conclusions
              </button>
              <button 
                onClick={() => setStep(AppStep.FINALIZE)} 
                className="px-8 py-3 bg-green-700 text-white rounded-2xl font-bold hover:bg-green-800 transition-all flex items-center gap-3"
              >
                Vista Final <i className="fas fa-check-circle"></i>
              </button>
            </div>

            <RichTextEditor 
              label="ORIENTACIONS PER A LA RESPOSTA EDUCATIVA" 
              value={report.orientations} 
              onChange={v => setReport({...report, orientations: v})} 
            />

            <div className="flex justify-center pt-6 no-print">
              <button 
                onClick={() => setStep(AppStep.FINALIZE)} 
                className="px-12 py-5 bg-green-700 text-white rounded-2xl font-black text-xl hover:bg-green-800 hover:scale-[1.02] transition-all flex items-center gap-4"
              >
                FINALITZAR INFORME <i className="fas fa-flag-checkered"></i>
              </button>
            </div>
          </div>
        )}

        {/* STEP 4: FINALIZE / PRINT */}
        {step === AppStep.FINALIZE && (
          <div className="space-y-10 animate-fadeIn">
            <div className="flex flex-col sm:flex-row justify-between no-print items-center gap-4 border-b pb-6">
              <button onClick={() => setStep(AppStep.ORIENTATIONS)} className="text-slate-500 font-bold hover:text-slate-800 flex items-center gap-2">
                <i className="fas fa-arrow-left"></i> Seguir editant
              </button>
              <div className="flex items-center gap-3">
                <button type="button" onClick={downloadAsWord} className="px-6 py-2.5 bg-blue-700 text-white rounded-xl font-bold hover:bg-blue-800 transition-all flex items-center gap-2 whitespace-nowrap">
                  <i className="fas fa-file-word"></i> DESCARREGAR WORD
                </button>
                <button type="button" onClick={() => window.print()} className="px-6 py-2.5 bg-slate-800 text-white rounded-xl font-bold hover:bg-slate-900 transition-all flex items-center gap-2">
                  <i className="fas fa-print"></i> IMPRIMIR
                </button>
              </div>
            </div>

            <div ref={reportContentRef} className="bg-white p-12 sm:p-16 border report-container rounded-none sm:rounded-[2rem] prose prose-slate max-w-none relative overflow-hidden shadow-sm">
              {/* Capçalera oficial tipus Generalitat */}
              <div className="flex justify-between items-start mb-16 border-b-2 border-slate-900 pb-6">
                <div className="flex items-center gap-6">
                  <Logo className="w-24 h-24" />
                  <div className="flex flex-col gap-1">
                    <h1 className="text-xl font-black text-slate-900 m-0 p-0 leading-none uppercase tracking-tight">EAP B-50</h1>
                    <p className="text-[11px] font-bold text-slate-600 m-0 uppercase tracking-widest leading-tight">Generalitat de Catalunya<br/>Departament d'Educació</p>
                    <p className="text-[10px] text-slate-400 m-0 uppercase font-medium">Serveis Territorials al Vallès Occidental</p>
                  </div>
                </div>
                <div className="text-right flex flex-col items-end">
                   <div className="bg-slate-900 text-white px-3 py-1 text-[10px] font-black uppercase tracking-widest mb-2">Informe Oficial</div>
                   <p className="text-[10px] font-bold text-slate-800 m-0 uppercase">NESE - Decret 150/2017</p>
                </div>
              </div>

              <div className="mb-12">
                <h1 className="text-center text-3xl font-black uppercase underline decoration-slate-300 underline-offset-8 mb-10">Informe Psicopedagògic</h1>

                <div className="grid grid-cols-2 gap-y-6 gap-x-12 bg-slate-50 p-8 rounded-2xl border border-slate-100 mb-10">
                  <div className="flex flex-col gap-1">
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Alumne/a</span>
                    <span className="text-base font-bold text-slate-900">{report.studentName || '________________________________'}</span>
                  </div>
                  <div className="flex flex-col gap-1">
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Nivell Educatiu</span>
                    <span className="text-base font-bold text-slate-900">{report.schoolLevel || '________________________________'}</span>
                  </div>
                  <div className="flex flex-col gap-1">
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Curs Escolar</span>
                    <span className="text-base font-bold text-slate-900">{report.schoolYear || '________________________________'}</span>
                  </div>
                  <div className="flex flex-col gap-1">
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Data</span>
                    <span className="text-base font-bold text-slate-900">{new Date().toLocaleDateString('ca-ES', { day: 'numeric', month: 'long', year: 'numeric' })}</span>
                  </div>
                </div>
              </div>

              {/* CONTINGUT DE L'INFORME */}
              <div className="space-y-12 report-content">
                <section>
                  <div className="mb-8 border-l-4 border-slate-900 pl-4">
                    <h2 className="text-xl font-black uppercase text-slate-900 m-0">1. Conclusions de l'Avaluació</h2>
                  </div>
                  <div className="text-slate-800 text-base" dangerouslySetInnerHTML={{__html: report.conclusions}} />
                </section>

                <div className="page-break my-16"></div>

                <section>
                  <div className="mb-8 border-l-4 border-slate-900 pl-4">
                    <h2 className="text-xl font-black uppercase text-slate-900 m-0">2. Orientacions per a la Resposta Educativa</h2>
                  </div>
                  <div className="text-slate-800 text-base" dangerouslySetInnerHTML={{__html: report.orientations}} />
                </section>
              </div>

              <div className="mt-32 pt-12 border-t border-slate-100 flex justify-end">
                <div className="text-center w-64">
                  <div className="h-24 flex items-center justify-center italic text-slate-300 text-[10px] mb-2 uppercase tracking-tighter">Signatura del professional de l'EAP</div>
                  <hr className="border-slate-300" />
                  <p className="mt-4 font-black text-slate-900 text-sm">Equip d'Orientació B-50</p>
                  <p className="text-[9px] text-slate-500 uppercase font-bold tracking-widest">Referent de l'Informe</p>
                </div>
              </div>
            </div>
          </div>
        )}
      </main>

      <footer className="mt-20 py-8 border-t border-slate-200 text-center no-print">
        <p className="text-slate-400 text-[10px] font-bold uppercase tracking-[0.2em] flex items-center justify-center gap-2">
          Eina Professional de l'EAP B-50 • Castellar del Vallès
        </p>
      </footer>
    </div>
  );
};

export default App;

