              >
                {loading ? <><i className="fas fa-circle-notch fa-spin"></i> Elaborant Orientacions...</> : <>ELABORAR ORIENTACIONS <i className="fas fa-wand-magic-sparkles"></i></>}
              </button>
            </div>
