      <head>
        <meta charset='utf-8'>
        <title>Informe NESE</title>
        <style>
          body { font-family: 'Arial', sans-serif; line-height: 1.5; color: #333; padding: 20px; }
          h1 { color: #065f46; text-align: center; text-transform: uppercase; border-bottom: 2px solid #065f46; padding-bottom: 10px; margin-bottom: 30px; }
          h2 { color: #065f46; text-transform: uppercase; margin-top: 40px; margin-bottom: 20px; border-left: 5px solid #065f46; padding-left: 10px; font-size: 16pt; }
          h3 { color: #065f46; margin-top: 25px; margin-bottom: 15px; font-weight: bold; font-size: 14pt; }
          p { margin-bottom: 20px; text-align: justify; line-height: 1.5; }
          ul { margin-bottom: 20px; padding-left: 20px; }
          li { margin-bottom: 12px; line-height: 1.5; }
          .intro-text { margin-bottom: 30px; text-align: justify; color: #4b5563; }
          .data-table { width: 100%; border-collapse: collapse; margin-bottom: 40px; background-color: #f0fdf4; }
          .data-table td { padding: 15px; border: 1px solid #d1fae5; }
          .label { font-weight: bold; color: #065f46; font-size: 10pt; text-transform: uppercase; }
          .value { font-size: 12pt; }
          .section-break { margin-top: 50px; }
        </style>
      </head>
      <body>
    `;

    const footer = "</body></html>";

    const introParagraph = `<p class="intro-text">En l'avaluació psicopedagògica de <strong>${report.studentName || 'l\'alumne/a'}</strong> observem diferents aspectes a tenir presents per oferir una resposta educativa davant d'unes necessitats específiques relacionades amb els següents àmbits:</p>`;

    const content = `
      <h1>Informe Psicopedagògic</h1>
      <table class="data-table">
        <tr>
          <td><span class="label">Alumne/a:</span><br/><span class="value">${report.studentName || 'N/A'}</span></td>
          <td><span class="label">Nivell:</span><br/><span class="value">${report.schoolLevel || 'N/A'}</span></td>
        </tr>
        <tr>
          <td><span class="label">Curs Escolar:</span><br/><span class="value">${report.schoolYear || 'N/A'}</span></td>
          <td><span class="label">Data:</span><br/><span class="value">${new Date().toLocaleDateString('ca-ES')}</span></td>
        </tr>
      </table>

      ${introParagraph}

      <div class="section-break">
        <h2>1. Conclusions de l'Avaluació</h2>
        <div>${report.conclusions}</div>
      </div>

      <br clear="all" style="page-break-before:always" />

      <div class="section-break">
        <h2>2. Orientacions per a la Resposta Educativa</h2>
        <div>${report.orientations}</div>
      </div>
    `;

    const sourceHTML = header + content + footer;

    const blob = new Blob(['\ufeff', sourceHTML], {
      type: 'application/msword'
    });

    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Informe_NESE_${report.studentName || 'alumne'}.doc`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // PANTALLA DE BLOQUEIG
  if (!authorized) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-6">
        <div className="w-full max-w-md bg-white rounded-[2.5rem] shadow-2xl p-10 text-center animate-fadeIn">
          <div className="w-24 h-24 bg-emerald-700 text-white rounded-3xl flex items-center justify-center text-4xl shadow-xl shadow-emerald-700/20 mx-auto mb-8">
            <i className="fas fa-lock"></i>
          </div>
          <h2 className="text-2xl font-black text-slate-800 mb-2">Accés Protegit</h2>
          <p className="text-slate-500 text-sm mb-8">Introdueix el codi per començar a redactar informes.</p>

          <form onSubmit={handleAuth} className="space-y-4">
            <input 
              type="password" 
              value={passInput} 
              onChange={e => setPassInput(e.target.value)} 
              className={`w-full p-4 bg-slate-100 border-2 rounded-2xl outline-none text-center font-bold tracking-[0.5em] focus:ring-4 focus:ring-emerald-50 transition-all ${authError ? 'border-red-400 shake' : 'border-transparent focus:border-emerald-600'}`}
              placeholder="••••••"
              autoFocus
            />
            <button type="submit" className="w-full py-4 bg-emerald-700 text-white rounded-2xl font-black hover:bg-emerald-800 transition-all shadow-lg shadow-emerald-700/20 uppercase tracking-widest">
              Entrar
            </button>
          </form>
          {authError && <p className="mt-4 text-red-500 text-xs font-bold uppercase animate-pulse">Codi incorrecte</p>}
        </div>
        <style>{`
          .shake { animation: shake 0.4s ease-in-out; }
          @keyframes shake {
            0%, 100% { transform: translateX(0); }
            25% { transform: translateX(-8px); }
            75% { transform: translateX(8px); }
          }
        `}</style>
      </div>
    );
  }

  return (
