                  <label
                    htmlFor="file-upload"
                    className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-5 py-2.5 bg-slate-800 hover:bg-slate-900 text-white rounded-xl cursor-pointer transition-all font-black text-[10px] uppercase tracking-widest ${fileProcessing ? 'opacity-50 cursor-not-allowed' : ''}`}
                  >
