          </button>
          <a 
            href="https://ai.google.dev/gemini-api/docs/billing" 
            target="_blank" 
            rel="noopener noreferrer"
            className="text-[10px] font-bold text-emerald-600 hover:underline uppercase tracking-widest"
          >
            Documentació sobre facturació
          </a>
        </div>
      </div>
    );
