   * OCR and image analysis for educational reports.
   */
  async visionExtractText(imagesBase64: string[]): Promise<string> {
    const imageParts = imagesBase64.map(base64 => ({
      inlineData: {
        data: base64.split(',')[1],
        mimeType: 'image/jpeg'
      }
    }));

